# -*- coding: utf-8 -*-"""pack_samples.py — 把「要拿去做离线复现 / 送检」的样本打成**一个自足 tgz**（含依赖闭包）。为什么需要它：单发一个 `painting/<名>` 或 `spinepainting/<名>` **是不够的** ——`compose_paintings_v2.py` 与 `extract_spine_v2.py` 都要读`Output/dependency_manifest.json`（官方依赖表）才能定位纹理包；漏一个依赖包，对方拿到手只能跑一半，还要来回一轮才知道缺哪个。本脚本按依赖表算**闭包**，一次打全。（live2d 是自包含单文件，本来就够，但一并打进来便于一次发完。）用法:  py -3 scripts/diag/pack_samples.py --live2d aersasi_2,aersasi_3,ougen_8 --out l2d_samples.tgz  py -3 scripts/diag/pack_samples.py --painting antu_2 --spine antu_2 --out full_samples.tgz  py -3 scripts/diag/pack_samples.py --live2d aersasi_2 --dry-run        # 只列清单/体积/缺件产物形状（**解包即用**：`tar -xzf samples.tgz -C <仓库根>`，路径与仓库一致）:  files/AssetBundles/live2d/<名>  files/AssetBundles/painting/<名>            + <名>_tex / _res / _face / _bj …  files/AssetBundles/spinepainting/<名>       + <名>_res …  Output/dependency_manifest.json             （--with-manifest，默认开；缺它两步都跑不了）判据（退出码即结论，别上传半包）:  0 = 闭包内全部条目都在盘上 · 已写入 tgz · 回读条目数与预期一致（并打印 tgz 的 sha256）  1 = 有缺件（依赖表列到但盘上没有）→ 逐条打印，先补齐再打包"""import argparseimport hashlibimport jsonimport osimport sysimport tarfileHERE = os.path.dirname(os.path.abspath(__file__))S = os.path.dirname(HERE)ROOT = os.path.dirname(S)sys.path.insert(0, S)sys.stdout.reconfigure(encoding='utf-8', errors='replace')import paths as P  # noqa: E402SKIP_DEPS = {'custom_builtin'}def _load_manifest(path):    if not os.path.isfile(path):        return None    with open(path, encoding='utf-8') as f:        return json.load(f)def _bundle_path(key):    """资源名（`painting/antu_2`）→ 盘上文件；兼容 <名>.bundle 变体。"""    p = os.path.join(P.AB, key)    if os.path.isfile(p):        return p    if os.path.isfile(p + '.bundle'):        return p + '.bundle'    return Nonedef _siblings(key):    """同目录下 `<名>_*` 的兄弟包（有些部件包不在依赖表里，靠前缀兜住）。"""    cat, _, name = key.partition('/')    d = os.path.join(P.AB, cat)    out = []    if not os.path.isdir(d):        return out    for fn in os.listdir(d):        if fn.startswith(name + '_') and os.path.isfile(os.path.join(d, fn)):            out.append(f'{cat}/{fn}')    return outdef closure(keys, manifest):    """依赖闭包（BFS）；manifest 为 None 时只做同名前缀兜底。"""    seen, queue, missing = set(), list(keys), []    while queue:        k = queue.pop(0)        if k in seen or k in SKIP_DEPS:            continue        seen.add(k)        if manifest is not None:            for d in (manifest.get(k) or {}).get('deps') or []:                if d not in seen and d not in SKIP_DEPS:                    queue.append(d)        for sib in _siblings(k):            if sib not in seen:                queue.append(sib)    for k in sorted(seen):        if _bundle_path(k) is None:            missing.append(k)    return sorted(seen), missingdef main():    ap = argparse.ArgumentParser(description='打包样本（含依赖闭包）')    ap.add_argument('--live2d', default='', help='live2d 模型名，逗号分隔')    ap.add_argument('--painting', default='', help='立绘皮肤名，逗号分隔')    ap.add_argument('--spine', default='', help='Spine 皮肤名，逗号分隔')    ap.add_argument('--out', default='samples.tgz')    ap.add_argument('--with-manifest', action='store_true', default=True)    ap.add_argument('--no-manifest', dest='with_manifest', action='store_false')    ap.add_argument('--dry-run', action='store_true')    a = ap.parse_args()    keys = [f'live2d/{x}' for x in a.live2d.split(',') if x] \        + [f'painting/{x}' for x in a.painting.split(',') if x] \        + [f'spinepainting/{x}' for x in a.spine.split(',') if x]    if not keys:        print(__doc__)        return 2    if not os.path.isdir(P.AB):        print(f'XX 源包根不存在：{P.AB}\n   （换机器就设 AL_ASSETS_ROOT 指向含 files/ 的仓库根）')        return 2    mf = _load_manifest(P.MANIFEST_PATH)    if mf is None:        print(f'! 没有 {P.rel(P.MANIFEST_PATH)} ⇒ 只能按"同名前缀"兜底（可能漏依赖包）。\n'              f'  建议先跑：py -3 scripts/export_dependency_manifest.py --out '              f'"{P.MANIFEST_PATH}"（需要 files/AssetBundles/dependencies）')    keys_cl, missing = closure(keys, mf)    # 统一成 [(绝对路径, 包内路径)]：包内路径一律相对**仓库根** ⇒ 对方 `tar -xzf x -C <根>` 即用    entries = []    for k in keys_cl:        p = _bundle_path(k)        if p:            entries.append((p, os.path.join('files', 'AssetBundles',                                             os.path.relpath(p, P.AB))))    if a.with_manifest and os.path.isfile(P.MANIFEST_PATH):        entries.insert(0, (P.MANIFEST_PATH, 'Output/dependency_manifest.json'))    total = sum(os.path.getsize(p) for p, _ in entries)    print(f'仓库根 {P.ROOT}\n依赖表 {"已读" if mf else "缺"} · 闭包 {len(keys_cl)} 个资源 + '          f'{1 if entries and entries[0][1].startswith("Output/") else 0} 个台账')    for p, arc in entries:        print(f'  OK  {arc}  {os.path.getsize(p)/1048576:.2f} MB')    print(f'\n合计（未压缩）{total/1048576:.1f} MB')    if missing:        print(f'\nXX 缺件 {len(missing)} 个（依赖表列到、盘上没有）—— 先补齐再打包：')        for m in missing:            print(f'   {m}')        return 1    if a.dry_run:        print('\n[dry-run] 未写盘。')        return 0    with tarfile.open(a.out, 'w:gz') as tf:        for p, arc in entries:            tf.add(p, arcname=arc)    got = tarfile.open(a.out).getnames()    h = hashlib.sha256(open(a.out, 'rb').read()).hexdigest()    size = os.path.getsize(a.out)    print(f'\n已写入 {a.out}  {size/1048576:.1f} MB  sha256={h}')    print(f'回读条目 {len(got)} / 预期 {len(entries)}'          + ('  ✅' if len(got) == len(entries) else '  XX 条目数不符，别上传'))    print(f'\n解包（对方侧）：tar -xzf {os.path.basename(a.out)} -C <仓库根>')    return 0 if len(got) == len(entries) else 1if __name__ == '__main__':    sys.exit(main())